import{_ as t,o as e,c as o,a0 as i}from"./chunks/framework.Bogozrur.js";const u=JSON.parse('{"title":"Database Automation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/database.md","filePath":"guide/database.md"}'),s={name:"guide/database.md"};function n(r,a,d,l,c,h){return e(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="database-automation" tabindex="-1">Database Automation <a class="header-anchor" href="#database-automation" aria-label="Permalink to &quot;Database Automation&quot;">​</a></h1><p>Jengo provides an incredibly smooth out-of-the-box database experience, enabling you to start writing code instantly without setting up local MySQL servers.</p><h2 id="zero-config-sqlite" tabindex="-1">Zero-Config SQLite <a class="header-anchor" href="#zero-config-sqlite" aria-label="Permalink to &quot;Zero-Config SQLite&quot;">​</a></h2><p>By default, the Jengo Installer configures your new application to use an <strong>SQLite</strong> database.</p><p>During the installation process, the <code>DbInstaller</code> automatically:</p><ol><li>Parses your <code>app/Config/Database.php</code>.</li><li>Comments out the default MySQL block.</li><li>Uncomments the SQLite block and points it to <code>WRITEPATH . &#39;database.db&#39;</code>.</li></ol><h2 id="automatic-migrations" tabindex="-1">Automatic Migrations <a class="header-anchor" href="#automatic-migrations" aria-label="Permalink to &quot;Automatic Migrations&quot;">​</a></h2><p>After configuring the connection, the installer automatically executes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p>If you included the Auth suite (<code>--auth</code>), this means that the <code>users</code>, <code>auth_identities</code>, and <code>auth_logins</code> tables are created for you immediately. You can boot the application and register a user right away!</p><h2 id="switching-to-production-databases" tabindex="-1">Switching to Production Databases <a class="header-anchor" href="#switching-to-production-databases" aria-label="Permalink to &quot;Switching to Production Databases&quot;">​</a></h2><p>When you are ready to deploy or switch to a robust local database (like MySQL or PostgreSQL), simply open your <code>app/Config/Database.php</code>, comment the SQLite block back out, and uncomment your preferred database driver.</p>',12)])])}const b=t(s,[["render",n]]);export{u as __pageData,b as default};
